typedef bool Bool;
typedef int Int;
#define TRUE 1
#define FALSE 0

enum DozerTask
{
	DOZER_TASK_BUILD,
	DOZER_TASK_REPAIR,
	DOZER_TASK_FORTIFY,
	DOZER_NUM_TASKS
};

class DozerAIUpdate
{
public:
	virtual void d0() = 0;
	virtual void d1() = 0;
	virtual void d2() = 0;
	virtual void d3() = 0;
	virtual void d4() = 0;
	virtual void d5() = 0;
	virtual Bool isTaskPending(DozerTask task) = 0;
	virtual Bool isAnyTaskPending();
};

Bool DozerAIUpdate::isAnyTaskPending(void)
{
	for (Int i = 0; i < DOZER_NUM_TASKS; i++)
		if (isTaskPending((DozerTask)i))
			return TRUE;

	return FALSE;
}
